NEW_FILES = {'zoo_keeper/core/stanchion_run_forms.py': '"""What a run of retractable-belt queue stanchions is, in numbers: ONE place, no bpy.\n\nFactory roadmap 267. The walker, 2026-10-20, on what lines a queue indoors: "stanchion or stanchions are likley more\ncommon for banks and indoor common areas", "metal barriers are for outdoor concerts or riot protection from police",\nand a photo of the thing itself -- black posts on round weighted bases, a flat black belt pulled taut between each\npair at waist height, lanes switching back in front of a registration desk. Deli Counter lays a box office\'s queue as\nruns of this species, one straight run a slot: posts along the slot\'s width, a belt between each neighbouring pair.\n\nREFERENCE, the common retractable-belt stanchion as suppliers list it (no code governs one): a post about 38 in tall,\n2-1/2 in across, on a 14 in weighted base about 2 in high, the belt 2 in wide, pulled from a cassette in the post\'s head\nto the next post, 7-1/2 ft of belt the usual reach.\n  * `POST_R`, `HEAD_R`, `HEAD_H`: the post\'s tube and the cassette head the belt runs out of;\n  * `BASE_H`: the domed base\'s height. It is also the rule the crowd barrier learned in Zoo 1.118.1: Deli Counter\n    lays a room\'s floor finish as a 2 cm skin over the slab and stands props on the slab under it, so a base under\n    2 cm is buried -- this one stands 3 cm proud of that skin;\n  * `BELT_MAX`: the most belt between two posts, 7-1/2 ft; a run is as few posts as keep every span within it, the\n    spans equal; `MIN_BELT`, the least that shows between two bases\' rims, so the shortest run is two bases and\n    some belt, never two bases touching;\n  * `BELT_W`, `BELT_T`: the belt, 2 in high and drawn 6 mm thick (it is about 1), so it holds a pixel across a room.\n\nTHE FRAME is the module\'s own: X along the run, Y across (the base\'s diameter), Z up. Centre pivot, and the extents are\nexactly the slot\'s (w, d, h): the end bases\' rims are the run\'s ends, a base\'s diameter its depth, the heads\' tops its\ntop. ONE MATERIAL, one part, one submission: black powder coat, the belt in the same black.\n\nNO FACE OF ONE PART LIES ON ANOTHER\'S, and no open end shows: a post is open at both ends, its foot inside its base and\nits top inside its head; a base is open only at the floor, its top capped where the post rises through it; the belt\nis one band from the first post\'s axis to the last\'s, its ends inside the end heads and its 6 mm inside a head\'s\nflats -- a belt a span put two end faces on one plane inside every middle head. The bases\' rings are twelve-sided,\nsince at 14 in across eight would read as an octagon; the posts\' and heads\' are eight, as every tube\'s in Zoo.\n\nCOLLISION: each post, base to head, and the belt line -- a thin band at the belt\'s height from end post to end post --\nso a body cannot walk through a run, and a shot above or below the belt passes, as it would. Deli Counter writes no\nbox over a run (its `prop_species.SPECIES_OWNS_COLLISION`): a solid box would be cover the belt is not.\n"""\nfrom __future__ import annotations\n\nimport math\n\nfrom . import prims\n\nIN = 0.0254\nPOST_R = round(1.25 * IN, 5)          # a 2-1/2 in post\nHEAD_R = round(1.5 * IN, 5)           # the cassette head, 3 in across\nHEAD_H = round(4 * IN, 4)             # the head\'s height\nBASE_H = round(2 * IN, 4)             # the domed base: 2 in, 3 cm proud of a 2 cm floor skin\nBASE_TOP_R = round(1.75 * IN, 5)      # where the dome meets the post\nBELT_MAX = round(90 * IN, 4)          # 7-1/2 ft of belt\nBELT_W = round(2 * IN, 4)             # the belt\'s height\nBELT_T = 0.006                        # its thickness, drawn heavier than the real 1 mm\n#: the belt\'s centre under the head\'s top\nBELT_DROP = round(2 * IN, 4)\n#: the post\'s foot inside its base, under the base\'s top\nSINK = 0.01\n#: the least belt that shows between two bases\' rims: closer, and a run is two bases touching\nMIN_BELT = 0.2\nSIDES = 8\nBASE_SIDES = 12\nMAT = "steel"\nPART = "StanchionRun_Steel"\nFLAT = math.cos(math.pi / SIDES)\n\n\ndef _open(p, keep=()):\n    """``p`` with its two end caps (faces 0 and 1 of `prims.cyl`) dropped, but those in ``keep``."""\n    q = dict(p)\n    q["faces"] = [f for i, f in enumerate(p["faces"]) if i >= 2 or i in keep]\n    return q\n\n\ndef post_xs(w, base_r):\n    """The posts\' centres along a run ``w`` long: the end bases\' rims at its ends, as few posts as keep every belt\n    within `BELT_MAX`, the spans equal."""\n    x0, x1 = -w / 2.0 + base_r, w / 2.0 - base_r\n    spans = max(1, math.ceil((x1 - x0) / BELT_MAX - 1e-9))\n    return [x0 + (x1 - x0) * i / spans for i in range(spans + 1)]\n\n\ndef plan(w, d, h):\n    """The run for a slot of ``w`` x ``d`` x ``h`` (X along it): ``{prims, collision, facts}``."""\n    w, d, h = float(w), float(d), float(h)\n    base_r = d / 2.0\n    if w - 4 * base_r < MIN_BELT:\n        raise ValueError("a stanchion run %.3f m long cannot stand two posts on %.3f m bases with %.2f m of belt "\n                         "between them" % (w, d, MIN_BELT))\n    if h < BASE_H + HEAD_H + 0.3:\n        raise ValueError("a stanchion %.3f m tall cannot hold its head over its base" % h)\n    z0, z1 = -h / 2.0, h / 2.0\n    xs = post_xs(w, base_r)\n    head0 = z1 - HEAD_H\n    belt_z = z1 - BELT_DROP\n    out = []\n    for x in xs:\n        # the domed base, open at the floor, its top capped: the post rises through it\n        out.append(_open(prims.cyl(PART, MAT, (x, 0.0), base_r, z0, z0 + BASE_H, segments=BASE_SIDES,\n                                   r_top=BASE_TOP_R), keep=(1,)))\n        # the post, from inside the base to inside the head\n        out.append(_open(prims.cyl(PART, MAT, (x, 0.0), POST_R, z0 + BASE_H - SINK, head0 + SINK, segments=SIDES)))\n        # the head, capped both ends: the post rises into its underside\n        out.append(prims.cyl(PART, MAT, (x, 0.0), HEAD_R, head0, z1, segments=SIDES))\n    # the belt: ONE band from the first post\'s axis to the last\'s, through every head between. A belt a span, end\n    # to end, put two belts\' end faces on one plane inside each middle head (the census\'s pair); the heads hide the\n    # joins either way\n    out.append(prims.box(PART, MAT, (xs[0], -BELT_T / 2, belt_z - BELT_W / 2),\n                         (xs[-1], BELT_T / 2, belt_z + BELT_W / 2)))\n    boxes = [((x - POST_R, -POST_R, z0), (x + POST_R, POST_R, z1)) for x in xs]\n    boxes.append(((xs[0], -BELT_T / 2, belt_z - BELT_W / 2), (xs[-1], BELT_T / 2, belt_z + BELT_W / 2)))\n    out, boxes = prims.fit_exact(out, (-w / 2, -d / 2, z0), (w / 2, d / 2, z1), boxes)\n    facts = {"tris": prims.tri_count(out), "posts": len(xs),\n             "span": round((xs[-1] - xs[0]) / max(1, len(xs) - 1), 4), "belt_z": round(belt_z, 4)}\n    return {"prims": out, "collision": boxes, "facts": facts}\n', 'zoo_keeper/recipes/stanchion_run.py': '"""stanchion_run recipe: one straight run of retractable-belt queue stanchions, posts and belt.\n\nFactory roadmap 267, the walker\'s 2026-10-20 photo of a queue indoors: black posts on round bases, a flat black belt\ntaut between them at waist height. `core.stanchion_run_forms` lays the run out in pure Python -- the reference sizes,\nthe posts\' spacing, why no two faces meet and no open end shows -- and `bpylayer.prim_mesh` builds those lists vertex\nfor vertex, so what its tests measure is what ships.\n\nOne material whatever the length: black powder coat, the belt in the same black. Collision: the posts and the belt\nline, as the plan gives them.\n"""\nfrom __future__ import annotations\n\nfrom ..bpylayer import prim_mesh\nfrom ..core import stanchion_run_forms as F\n\n\ndef build(plan, streams, collection):\n    w = plan["dimensions"]["width"]\n    d = plan["dimensions"]["depth"]\n    h = plan["dimensions"]["height"]\n    got = F.plan(w, d, h)\n    mats = {F.MAT: (f"M_StanchionRun_{plan[\'material\']}", list(plan["color"]), plan["material"])}\n    objs = prim_mesh.build(got["prims"], collection, plan, streams.stream("wear"), mats, texel=1.2)\n    print(f"[stanchion_run] {w:.3f} x {d:.3f} x {h:.3f} tris={got[\'facts\'][\'tris\']} posts={got[\'facts\'][\'posts\']}")\n    return {"objects": objs, "collision_boxes": got["collision"], "attachments": {},\n            "stanchion_run": {"tris": got["facts"]["tris"], "posts": got["facts"]["posts"]}}\n', 'zoo_keeper/genome/species/stanchion_run.json': '{\n  "species": "stanchion_run",\n  "version": 1,\n  "license": {\n    "construction_knowledge": "CC0",\n    "notes": "Factory roadmap 267. The walker, 2026-10-20: \'stanchion or stanchions are likley more common for banks and indoor common areas\', \'metal barriers are for outdoor concerts or riot protection from police\', \'retractable belt stanchion\', and a photo -- black posts on round weighted bases, a flat black belt taut between each pair at waist height, lanes switching back in front of a desk. REFERENCE: the common retractable-belt queue stanchion -- a 38 in post 2-1/2 in across on a 14 in weighted base 2 in high, a cassette head, a 2 in belt, 7-1/2 ft of reach -- black powder coat. One straight run a slot: posts along its width, one belt through them (`core/stanchion_run_forms.py`). The base stands 3 cm proud of a building\'s 2 cm floor skin (Zoo 1.118.1\'s lesson). Collision: the posts and the belt line; a body cannot walk through, a shot above or below the belt passes. BUILT: 168 tris for a two-post run, 246 at the default 4.6 m, 558 at 12 m (2026-10-20)."\n  },\n  "dimensions": {\n    "width": {\n      "min": 1.1,\n      "max": 12.0,\n      "default": 4.6\n    },\n    "depth": {\n      "min": 0.3,\n      "max": 0.42,\n      "default": 0.356\n    },\n    "height": {\n      "min": 0.9,\n      "max": 1.05,\n      "default": 0.97\n    }\n  },\n  "parts": [\n    "StanchionRun_Steel"\n  ],\n  "params": {},\n  "materials": {\n    "default": "metal_painted",\n    "options": [\n      "metal_painted"\n    ]\n  },\n  "styles": {\n    "default": {\n      "material": "metal_painted",\n      "color": [\n        0.045,\n        0.045,\n        0.05\n      ],\n      "wear": 0.12,\n      "bevel": 0.0\n    },\n    "delco": {\n      "material": "metal_painted",\n      "color": [\n        0.045,\n        0.045,\n        0.05\n      ],\n      "wear": 0.25,\n      "bevel": 0.0,\n      "ambient": 0.35\n    },\n    "center_city": {\n      "material": "metal_painted",\n      "color": [\n        0.045,\n        0.045,\n        0.05\n      ],\n      "wear": 0.1,\n      "bevel": 0.0,\n      "ambient": 0.15\n    },\n    "industrial_flats": {\n      "material": "metal_painted",\n      "color": [\n        0.05,\n        0.05,\n        0.05\n      ],\n      "wear": 0.4,\n      "bevel": 0.0,\n      "ambient": 0.45\n    },\n    "rockay": {\n      "material": "metal_painted",\n      "color": [\n        0.045,\n        0.045,\n        0.05\n      ],\n      "wear": 0.2,\n      "bevel": 0.0,\n      "ambient": 0.05\n    }\n  },\n  "budgets": {\n    "tris_lod0": 600\n  },\n  "attachments": [],\n  "collision": true,\n  "match_priority": 0,\n  "keywords": [\n    "stanchion run",\n    "queue line",\n    "queue lane",\n    "retractable belt stanchion",\n    "stanchion_run"\n  ]\n}\n', 'tests/test_stanchion_run.py': '"""stanchion_run (1.119.0): one straight run of retractable-belt queue stanchions, posts and belt.\n\nFactory roadmap 267, the walker, 2026-10-20: "stanchion or stanchions are likley more common for banks and indoor\ncommon areas", "metal barriers are for outdoor concerts or riot protection from police", "retractable belt stanchion",\nand a photo of a queue lined with them. `core.stanchion_run_forms` is the plan, drawn from a slot\'s box alone; the\nrecipe builds the same lists through `bpylayer.prim_mesh`. Pure: nothing here needs Blender. Every test here fails on\n1.118.1, which has no such species.\n"""\nimport itertools\nimport math\n\nimport pytest\n\nfrom zoo_keeper.core import genome, intent, kit, prims\nfrom zoo_keeper.core import stanchion_run_forms as F\n\nIN = 0.0254\n#: lengths either side of each place a run takes another post (d 0.356: 2.642, 4.928, 7.214 ...), and the genome\'s ends\nWIDTHS = (1.1, 1.5, 2.64, 2.65, 4.6, 4.92, 4.94, 9.0, 12.0)\nSIZES = list(itertools.product(WIDTHS, (0.3, 0.356, 0.42), (0.9, 0.97, 1.05)))\n\n\ndef test_stanchion_run_is_discovered_and_validates():\n    assert "stanchion_run" in genome.list_species()\n    g = genome.load_species("stanchion_run")\n    assert genome.validate_genome(g) == []\n    assert g["collision"] is True\n    assert g["parts"] == [F.PART]\n    assert g["materials"] == {"default": "metal_painted", "options": ["metal_painted"]}\n\n\ndef test_its_keywords_are_its_own_and_move_no_other_species(monkeypatch):\n    """A prompt resolves by keyword (`intent._find_species`), so a new genome whose words overlap an old one\'s would\n    quietly change what that prompt makes -- `queue_stanchion`\'s "belt barrier" and "queue stanchion" in particular.\n    Every one of this genome\'s words resolves to it, and every other genome\'s word resolves as it did without it."""\n    words = dict(intent._species_keywords())\n    mine = words["stanchion_run"][0]\n    assert mine and all(intent._find_species(k) == "stanchion_run" for k in mine)\n    others = [k for sp, (keys, _p) in words.items() if sp != "stanchion_run" for k in keys]\n    with_it = [intent._find_species(k) for k in others]\n    without = {sp: v for sp, v in words.items() if sp != "stanchion_run"}\n    monkeypatch.setattr(intent, "_species_keywords", lambda: without)\n    assert [intent._find_species(k) for k in others] == with_it\n    # the probe can see a move: a word that extends an old one takes that one\'s plural\n    assert intent._find_species("queue stanchions") == "queue_stanchion"\n    monkeypatch.setattr(intent, "_species_keywords", lambda: dict(without, x=(["queue stanchions"], 0)))\n    assert intent._find_species("queue stanchions") == "x"\n\n\ndef _plan_slot(material, dims=(4.6, 0.356, 0.97)):\n    return kit.plan_kit({"building_id": "arena_a02", "slots": [{\n        "slot_id": "queue_run_0", "role": "prop", "size_mod": "full", "style": 10, "material": material,\n        "species": "stanchion_run", "kit_axis": "material",\n        "transform": {"translation": [0.0, 0.0, dims[2] / 2], "rot_y": 0.0, "scale": [1.0, 1.0, 1.0]},\n        "fit": {"dims": list(dims), "pivot": "center", "openings": [], "collision": "convex"}}]},\n        theme="delco_1997", style=1)\n\n\ndef test_a_slot_in_its_own_kind_plans_as_the_species():\n    """A run as Deli Counter writes one -- in the species\' own kind, `metal_painted`, the dartboard\'s rule -- plans as\n    the species at the theme the levels build in, with no fallback and no `_m` in its stem."""\n    plan = _plan_slot("metal_painted")\n    assert plan["species_fallbacks"] == []\n    (m,) = plan["modules"]\n    assert m["species"] == "stanchion_run"\n    assert m["stem"] == "prop_stanchion_run_delco_1997_10_w460_d36_h97", m["stem"]\n\n\ndef test_the_defaults_are_the_reference_stanchion():\n    g = genome.load_species("stanchion_run")["dimensions"]\n    # a 38 in post on a 14 in base; the default run is two belts\' reach\n    assert math.isclose(g["height"]["default"], 38 * IN, abs_tol=0.01)\n    assert math.isclose(g["depth"]["default"], 14 * IN, abs_tol=1e-3)\n    # a 2-1/2 in post, a 2 in belt, 7-1/2 ft of it, the base 2 in high\n    assert (round(2 * F.POST_R / IN, 3), round(F.BELT_W / IN, 3), round(F.BELT_MAX / IN, 3),\n            round(F.BASE_H / IN, 3)) == (2.5, 2.0, 90.0, 2.0)\n    assert F.plan(g["width"]["default"], g["depth"]["default"], g["height"]["default"])["facts"]["posts"] == 3\n    # the belt\'s centre at waist height, about 36 in up\n    assert abs(g["height"]["default"] - F.BELT_DROP - 36 * IN) < 0.03\n\n\n@pytest.mark.parametrize("w,d,h", SIZES)\ndef test_the_extents_are_exactly_the_slots(w, d, h):\n    lo, hi = prims.bounds(F.plan(w, d, h)["prims"])\n    for a, (want_lo, want_hi) in enumerate(((-w / 2, w / 2), (-d / 2, d / 2), (-h / 2, h / 2))):\n        assert math.isclose(lo[a], want_lo, abs_tol=1e-9) and math.isclose(hi[a], want_hi, abs_tol=1e-9)\n\n\n@pytest.mark.parametrize("w,d,h", SIZES)\ndef test_no_face_lies_on_another(w, d, h):\n    assert prims.coincident_pairs(F.plan(w, d, h)["prims"]) == []\n\n\ndef test_the_coincidence_check_can_see_a_pair():\n    """The control: two belts a span, end to end, put their end faces on one plane inside the middle head -- the pair\n    one belt through every head removes -- and the probe reports it."""\n    xs = F.post_xs(4.6, 0.178)\n    a = prims.box(F.PART, F.MAT, (xs[0], -F.BELT_T / 2, 0.4), (xs[1], F.BELT_T / 2, 0.45))\n    b = prims.box(F.PART, F.MAT, (xs[1], -F.BELT_T / 2, 0.4), (xs[2], F.BELT_T / 2, 0.45))\n    assert prims.coincident_pairs([a, b])\n\n\n@pytest.mark.parametrize("w,d,h", SIZES)\ndef test_the_posts_are_as_few_as_keep_every_belt_within_its_reach(w, d, h):\n    xs = F.post_xs(w, d / 2)\n    spans = [b - a for a, b in zip(xs, xs[1:])]\n    assert max(spans) <= F.BELT_MAX + 1e-9\n    assert max(spans) - min(spans) < 1e-9\n    # one post fewer and a belt would be past its reach\n    assert (xs[-1] - xs[0]) / max(1, len(spans) - 1) > F.BELT_MAX or len(spans) == 1\n    # the end bases\' rims are the run\'s ends, and no two bases touch\n    assert math.isclose(xs[0] - d / 2, -w / 2) and math.isclose(xs[-1] + d / 2, w / 2)\n    assert min(spans) - d >= F.MIN_BELT - 1e-9\n\n\ndef _boundary_loops(p):\n    """The open ends of a primitive: its edges used by one face, chained into loops."""\n    count = {}\n    for f in p["faces"]:\n        for a, b in zip(f, f[1:] + f[:1]):\n            k = (min(a, b), max(a, b))\n            count[k] = count.get(k, 0) + 1\n    nxt = {}\n    for (a, b), n in count.items():\n        if n == 1:\n            nxt.setdefault(a, []).append(b)\n            nxt.setdefault(b, []).append(a)\n    loops, seen = [], set()\n    for start in nxt:\n        if start in seen:\n            continue\n        loop, prev, cur = [start], None, start\n        seen.add(start)\n        while True:\n            cand = [v for v in nxt[cur] if v != prev]\n            if not cand or cand[0] == start:\n                break\n            prev, cur = cur, cand[0]\n            if cur in seen:\n                break\n            seen.add(cur)\n            loop.append(cur)\n        loops.append(loop)\n    return loops\n\n\ndef _half_spaces(p):\n    """``p`` as a convex solid: each face\'s plane and each open end\'s, every normal away from its centroid."""\n    vs = p["verts"]\n    c = [sum(v[a] for v in vs) / len(vs) for a in range(3)]\n    out = []\n    for loop in [list(f) for f in p["faces"]] + _boundary_loops(p):\n        pts = [vs[i] for i in loop]\n        n = [0.0, 0.0, 0.0]\n        for (x0, y0, z0), (x1, y1, z1) in zip(pts, pts[1:] + pts[:1]):\n            n[0] += (y0 - y1) * (z0 + z1)\n            n[1] += (z0 - z1) * (x0 + x1)\n            n[2] += (x0 - x1) * (y0 + y1)\n        ln = math.sqrt(sum(x * x for x in n))\n        n = [x / ln for x in n]\n        dd = sum(n[a] * pts[0][a] for a in range(3))\n        if sum(n[a] * c[a] for a in range(3)) > dd:\n            n, dd = [-x for x in n], -dd\n        out.append((n, dd))\n    return out\n\n\ndef _inside(v, solid):\n    return all(sum(n[a] * v[a] for a in range(3)) - dd < -1e-7 for n, dd in solid)\n\n\n@pytest.mark.parametrize("w,d,h", [(4.6, 0.356, 0.97), (1.1, 0.3, 0.9), (12.0, 0.42, 1.05), (2.65, 0.356, 0.97)])\ndef test_no_open_end_shows(w, d, h):\n    """Every end left open lies strictly inside another member -- a post\'s foot in its base, its top in its head --\n    but a base\'s underside, which is the floor\'s: it lies on the slot\'s bottom face."""\n    got = F.plan(w, d, h)\n    ps = got["prims"]\n    solids = [_half_spaces(p) for p in ps]\n    inside = on_floor = 0\n    for i, p in enumerate(ps):\n        for loop in _boundary_loops(p):\n            if all(math.isclose(p["verts"][vi][2], -h / 2, abs_tol=1e-12) for vi in loop):\n                on_floor += 1\n                continue\n            inside += 1\n            for vi in loop:\n                assert any(_inside(p["verts"][vi], solids[j]) for j in range(len(ps)) if j != i), (i, p["verts"][vi])\n    posts = got["facts"]["posts"]\n    assert (on_floor, inside) == (posts, 2 * posts)\n\n\n@pytest.mark.parametrize("w,d,h", [(4.6, 0.356, 0.97), (1.1, 0.3, 0.9), (12.0, 0.42, 1.05)])\ndef test_the_belt_runs_through_every_head_and_ends_inside_the_end_ones(w, d, h):\n    got = F.plan(w, d, h)\n    ps = got["prims"]\n    (belt,) = [p for p in ps if len(p["faces"]) == 6]\n    heads = [p for p in ps if len(p["faces"]) == 2 + F.SIDES]\n    assert len(heads) == got["facts"]["posts"]\n    blo, bhi = prims.bounds([belt])\n    for head in heads:\n        hlo, hhi = prims.bounds([head])\n        # inside every head\'s height, its 6 mm inside a head\'s flats\n        assert hlo[2] < blo[2] and bhi[2] < hhi[2]\n        assert bhi[1] < F.HEAD_R * F.FLAT\n    # its two end faces inside the end heads\n    end_heads = [_half_spaces(heads[0]), _half_spaces(heads[-1])]\n    for v in belt["verts"]:\n        if math.isclose(v[0], blo[0]) or math.isclose(v[0], bhi[0]):\n            assert any(_inside(v, s) for s in end_heads), v\n    assert math.isclose((blo[2] + bhi[2]) / 2, h / 2 - F.BELT_DROP, abs_tol=1e-9)\n\n\ndef test_an_open_end_is_narrower_than_what_hides_it():\n    assert F.POST_R < F.HEAD_R * F.FLAT and F.POST_R < F.BASE_TOP_R * math.cos(math.pi / F.BASE_SIDES)\n    assert 0 < F.SINK < F.BASE_H and F.SINK < F.HEAD_H\n    assert F.BELT_T / 2 < F.HEAD_R * F.FLAT and F.BELT_W < F.HEAD_H\n\n\ndef test_the_base_stands_proud_of_a_floor_skin():\n    """Deli Counter lays a room\'s floor finish as a 2 cm skin over the slab and stands a prop on the slab under it (its\n    `floors.SKIN_THICK`): the crowd barrier\'s 9.5 mm feet were buried whole (Zoo 1.118.1). A base clears that skin by a\n    centimetre or more, at every size."""\n    skin = 0.02\n    for w, d, h in SIZES:\n        bases = [p for p in F.plan(w, d, h)["prims"] if len(p["faces"]) == 1 + F.BASE_SIDES]\n        assert len(bases) == F.plan(w, d, h)["facts"]["posts"]\n        assert all(max(v[2] for v in p["verts"]) - (-h / 2) >= skin + 0.01 for p in bases)\n\n\ndef test_one_material_one_part_one_submission_inside_the_budget():\n    budget = genome.load_species("stanchion_run")["budgets"]["tris_lod0"]\n    worst = 0\n    for w, d, h in SIZES:\n        got = F.plan(w, d, h)\n        assert {p["mat"] for p in got["prims"]} == {F.MAT}\n        assert {p["part"] for p in got["prims"]} == {F.PART}\n        worst = max(worst, got["facts"]["tris"])\n    assert worst <= budget, (worst, budget)\n\n\n@pytest.mark.parametrize("w,d,h", [(4.6, 0.356, 0.97), (1.1, 0.3, 0.9), (12.0, 0.42, 1.05)])\ndef test_the_collision_is_the_posts_and_the_belt_line(w, d, h):\n    """Each post base to head, and the belt line end post to end post: a body cannot walk through a run, and a shot\n    above or below the belt passes."""\n    got = F.plan(w, d, h)\n    boxes = got["collision"]\n    posts, (belt_lo, belt_hi) = boxes[:-1], boxes[-1]\n    assert len(posts) == got["facts"]["posts"]\n    xs = F.post_xs(w, d / 2)\n    for (lo, hi), x in zip(posts, xs):\n        assert math.isclose(lo[2], -h / 2) and math.isclose(hi[2], h / 2)\n        assert math.isclose((lo[0] + hi[0]) / 2, x, abs_tol=1e-9)\n        assert math.isclose(hi[1] - lo[1], 2 * F.POST_R, abs_tol=1e-9)\n    assert math.isclose(belt_lo[0], xs[0]) and math.isclose(belt_hi[0], xs[-1])\n    assert math.isclose(belt_hi[2] - belt_lo[2], F.BELT_W, abs_tol=1e-9)\n    assert belt_lo[2] > -h / 2 + 0.5\n\n\ndef test_a_box_too_small_for_the_run_is_refused():\n    with pytest.raises(ValueError):\n        F.plan(0.8, 0.42, 0.97)\n    with pytest.raises(ValueError):\n        F.plan(4.6, 0.356, 0.3)\n    F.plan(4 * 0.21 + F.MIN_BELT + 1e-6, 0.42, 0.97)\n'}
CHANGELOG = '## [1.119.0] - a run of retractable-belt queue stanchions, posts and belt: stanchion_run\n\n**The factory\'s roadmap 267, the walker, 2026-10-20**: asked what arena_a02\'s four steel barricades on its event floor\nwere for, they chose "queue lanes to the box office", then: "stanchion or stanchions are likley more common for banks\nand indoor common areas", "metal barriers are for outdoor concerts or riot protection from police", "retractable belt\nstanchion", and a photo -- black posts on round weighted bases, a flat black belt pulled taut between each pair at\nwaist height, lanes switching back in front of a desk. Deli Counter 0.243.0 lays a box office\'s queue as runs of this\nspecies. The steel `crowd_barrier` (1.118.0) stays for the outdoors.\n\n- **`stanchion_run`**, laid out in pure Python by `core/stanchion_run_forms.py` and built vertex for vertex through\n  `bpylayer.prim_mesh` (the crowd barrier\'s pattern), from the slot\'s box alone: one straight run, posts along its\n  width, ONE belt through them. A queue\'s switchback is several runs; a run is one slot.\n- **The numbers are the common retractable-belt stanchion\'s** (no code governs one): a 38 in post 2-1/2 in across on a\n  14 in base 2 in high, a cassette head 3 in across and 4 in tall, a 2 in belt -- drawn 6 mm thick so it holds a pixel\n  across a room -- its centre 2 in under the heads\' tops, and 7-1/2 ft of it the most between two posts. A run is as\n  few posts as keep every belt within that reach, the spans equal, the end bases\' rims at the run\'s ends; a run whose\n  bases would stand within 0.2 m of each other is refused. Defaults: two belts\' reach, 4.6 m, three posts; the genome\'s\n  ranges 1.1-12 x 0.3-0.42 x 0.9-1.05 m.\n- **The base stands proud of a building\'s floor skin**, the crowd barrier\'s lesson (1.118.1): Deli Counter lays a room\'s\n  finish as a 2 cm skin over the slab and stands props on the slab under it, and the base\'s 5 cm clears it by 3.\n- **No face of one part lies on another\'s, and no open end shows.** A post is open at both ends, its foot inside its\n  base and its top inside its head; a base is open only at the floor; the belt is one band from the first post\'s axis\n  to the last\'s, through every head -- a belt a span put two end faces on one plane inside each middle head, which the\n  census counts as a pair. The bases are twelve-sided (at 14 in across eight read as an octagon), the posts and heads\n  eight, as every tube\'s in Zoo.\n- **One material, one part, one submission:** black powder coat, `metal_painted` (0.045 / 0.045 / 0.05), the belt in\n  the same black, worn by theme.\n- **Collision: each post, and the belt line** -- a band at the belt\'s height from end post to end post -- so a body\n  cannot walk through a run and a shot above or below the belt passes, as it would. Deli Counter 0.243.0 writes no\n  box over a run (`prop_species.SPECIES_OWNS_COLLISION`): a solid box would be cover the belt is not.\n- **Its words are its own.** `stanchion run`, `queue line`, `queue lane`, `retractable belt stanchion`; none of\n  `queue_stanchion`\'s, a single post, whose `belt barrier` and `queue stanchion` keep resolving to it -- a word that\n  extended one of them would have taken its plural.\n\n**Measured, Blender 5.1.1** (the factory\'s `patches/zoo_stanchion_run/`):\n\n- `blender -b --python tools/coplanar_census.py -- --species stanchion_run bollard`: the run\'s three corners build at\n  168 / 246 / 558 tris with 0 pairs, first run; the bollard, the control that the census sees a pair, its known 2 / 2\n  / 1. "6 builds, 3 with coincident pairs, 0 that did not build". `CENSUS_BUILDS` 414 -> 417. 600 is the genome\'s\n  budget, inside the standard\'s small-clutter class (the factory\'s\n  `docs/reference/MODERN_LOW_POLY_ASSET_STANDARD.md`, section 1).\n- Four runs through `zoo_cli --build-kit` as Deli Counter writes a species that owns its collision (1.1, 3.0, 4.6 and\n  12 m): four modules PASS, each one visual mesh, one primitive, one material (`M_StanchionRun_metal_painted`), its\n  bounds the slot\'s exactly, and its `-colonly` proxy the posts and the belt line.\n\n### Tests\n- `tests/test_stanchion_run.py` (new): the genome validates; its keywords resolve to it and every other genome\'s word\n  resolves as it did without it, the probe seeing a planted move; a slot in its own kind plans\n  `prop_stanchion_run_delco_1997_10_w460_d36_h97` with no fallback; the defaults are the reference stanchion; over 81\n  sizes the extents are the slot\'s exactly, no face lies on another (the probe seeing the two-belt pair), the posts are\n  as few as keep every belt within its reach and no two bases touch, and the base clears a 2 cm skin; every open end\n  lies inside another member but the bases\' undersides, on the floor; the belt runs through every head and ends inside\n  the end ones; one material and one part inside the budget; the collision is the posts and the belt line; a box too\n  small is refused. It cannot import on 1.118.1, which has no such species.\n- `tests/test_material_options_closed.py`: `stanchion_run` is painted. `tests/test_coincident_faces.py`: the census\n  covers it, `CENSUS_BUILDS` 417. Four checks of these two fail on 1.118.1 (the factory\'s\n  `patches/zoo_stanchion_run/prove_tests_on_11181.out.txt`).\n\n'
OLD_VERSION, NEW_VERSION = '1.118.1', '1.119.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: zoo/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: zoo/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: zoo/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: zoo/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Zoo %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in zoo/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
